import { Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { Row, Col, ListGroup, Image, Form, Button, Card } from 'react-bootstrap';
import { FaTrash } from 'react-icons/fa';
import Message from '../components/Message';
import { addToCart, removeFromCart } from '../slices/cartSlice';
const CartScreen = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const cart = useSelector((state) => state.cart);
    const { cartItems } = cart;
    const addToCartHandler = async (product, qty) => {
        dispatch(addToCart({ ...product, qty }));
    }
    const removeFromCartHandler = async (id) => {
        dispatch(removeFromCart(id));
    }
    const checkoutHandler = () => {
        navigate('/login?redirect=/shipping');
    }
    return <Row>
        <Col md={8}>
            <div className='d-flex justify-content-between align-items-center mb-3'>
                <h1 className='mb-0'>Korpa</h1>
                <Link className='btn btn-sm btn-outline-secondary' to='/'>
                    ← Nazad na prodavnicu
                </Link>
            </div>
            {cartItems.length === 0 ? (
                <Message>Korpa je prazna <Link to='/'>Vrati se nazad</Link></Message>
            ) : (
                <ListGroup variant='flush'>
                    {cartItems.map((item) => (
                        <ListGroup.Item key={item._id}>
                            <Row>
                                <Col md={2}>
                                    <Image src={item.image} alt={item.name} fluid
                                        rounded />
                                </Col>
                                <Col md={3}>
                                    <Link
                                        to={`/product/${item._id}`}>{item.name}</Link>
                                </Col>
                                <Col md={2}>{item.price.toFixed(2)} RSD</Col>
                                <Col md={2}>
                                    <Form.Control
                                        as="select"
                                        value={item.qty}
                                        onChange={(e) => addToCartHandler(item,
                                            Number(e.target.value))}
                                    >
                                        {[...Array(item.countInStock).keys()].map
                                            ((x) => (
                                                <option key={x + 1} value={x + 1}>
                                                    {x + 1}
                                                </option>
                                            ))}
                                    </Form.Control>
                                </Col>
                                <Col md={2}>
                                    <Button variant="light" onClick={() =>
                                        removeFromCartHandler(item._id)}>
                                        <FaTrash />
                                    </Button>
                                </Col>
                            </Row>
                        </ListGroup.Item>
                    ))}
                </ListGroup>
            )}
        </Col>
        <Col md={4}>
            <Card>
                <ListGroup variant="flush">
                    <ListGroup.Item>
                        <h2>Ukupno: ({cartItems.reduce((acc, item) => acc +
                            item.qty, 0)}) proizvoda</h2>
                        {cartItems.reduce((acc, item) => acc + item.qty *
                            item.price, 0).toFixed(2)} RSD
                    </ListGroup.Item>
                    <ListGroup.Item>
                        <Button type='button' className='btn-block'
                            disabled={cartItems.length === 0}
                            onClick={checkoutHandler}>
                            Nastavi kupovinu
                        </Button>
                    </ListGroup.Item>
                </ListGroup>
            </Card>
        </Col>
    </Row>
}
export default CartScreen